import type { RequirementKey } from '../requirements/key'
import { parseReqKey, reqKey } from '../requirements/key'
import { requiredFields } from '../requirements/engine'
import { RULES_VERSION } from '../requirements/version'
import { refuseIfSubmitted, requireField } from './guards'
import { outstandingFields } from './queries'
import { PROFILE_BRIDGE, bridgeForField } from './profile-bridge'
import type { Action, ApplicationState, FieldState } from './state'
import type { ApplicantProfile } from '../requirements/rules'
import { fieldDef } from '../catalog'

/** The token is generated by the caller: this file stays free of randomness. */
export function createApplication(
  id: string,
  profile: ApplicantProfile,
  ownerToken: string,
): ApplicationState {
  return {
    id,
    ownerToken,
    rulesVersion: RULES_VERSION,
    profile,
    fields: {},
    submittedAt: null,
    transcript: [],
    orchestratorRejections: 0,
    documents: [],
  }
}

export function applicationReducer(
  state: ApplicationState,
  action: Action,
): ApplicationState {
  // Before the switch, so an action added later cannot escape it. Here rather
  // than in the route so the client path is covered by the same rule.
  refuseIfSubmitted(state)

  switch (action.type) {
    case 'SET_VALUE': {
      if (action.source === 'carried' && action.fromFieldId === undefined) {
        throw new Error(
          `Cannot carry into "${action.fieldId}": a carried value must record where it came from`,
        )
      }
      const next: FieldState = {
        value: action.value,
        // Typing it is confirming it; anything we derived still needs eyes.
        status: action.source === 'user' ? 'confirmed' : 'derived',
        provenance: {
          source: action.source,
          ...(action.documentId !== undefined && { documentId: action.documentId }),
          ...(action.confidence !== undefined && { confidence: action.confidence }),
          ...(action.fromFieldId !== undefined && { fromFieldId: action.fromFieldId }),
        },
      }
      const withValue = withField(state, action.fieldId, next)
      const bare = parseReqKey(action.fieldId)
      const entry = bare.instance === null ? bridgeForField(bare.fieldId) : undefined
      if (!entry) return withValue
      return applyProfilePatch(withValue, entry.toPatch(action.value), { writeFields: false })
    }

    case 'CLEAR_VALUE': {
      const current = state.fields[action.fieldId]
      // Clearing what was never recorded is a no-op, not an error.
      if (!current || current.value === null) return state
      // Provenance and rejection go with the value — both described the old
      // one, and a reviewer reads provenance to decide how hard to look.
      //
      // A bridged determinant's profile value is left as is: five of the
      // eight profile keys have no "unknown", and requirements must be
      // driven by something. Only the FIELD goes back to outstanding; the
      // engine keeps the last declaration until something re-patches it.
      return withField(state, action.fieldId, { value: null, status: 'empty' })
    }

    case 'CONFIRM': {
      const current = requireField(state, action.fieldId, 'confirm', { withValue: true })
      return withField(state, action.fieldId, {
        ...current,
        status: 'confirmed',
      })
    }

    case 'VERIFY': {
      const current = requireField(state, action.fieldId, 'verify')
      return withField(state, action.fieldId, { ...current, status: 'verified' })
    }

    case 'REJECT': {
      const current = requireField(state, action.fieldId, 'reject')
      return withField(state, action.fieldId, {
        ...current,
        status: 'rejected',
        rejection: { reason: action.reason, at: action.at },
      })
    }

    case 'SUPERSEDE': {
      const current = requireField(state, action.fieldId, 'supersede')
      return withField(state, action.fieldId, {
        ...current,
        status: 'superseded',
      })
    }

    case 'UPDATE_PROFILE':
      return applyProfilePatch(state, action.patch, { writeFields: true })

    case 'SUBMIT': {
      const outstanding = outstandingFields(state)
      if (outstanding.length > 0) {
        // Names what is missing: "cannot submit" with no reason is the
        // greyed-out button in a different costume.
        throw new Error(
          `Cannot submit: ${outstanding.length} still outstanding — ${outstanding.join(', ')}`,
        )
      }
      return { ...state, submittedAt: action.at }
    }

    case 'APPEND_TURN': {
      const expected = state.transcript.length + 1
      if (action.turn.seq !== expected) {
        throw new Error(
          `Turn seq ${action.turn.seq} is not the next one (expected ${expected})`,
        )
      }
      return { ...state, transcript: [...state.transcript, action.turn] }
    }

    case 'RECORD_REJECTION':
      return { ...state, orchestratorRejections: state.orchestratorRejections + 1 }

    case 'RECORD_DOCUMENT': {
      if (state.documents.some((d) => d.documentId === action.documentId)) {
        throw new Error(`Document ${action.documentId} is already recorded`)
      }
      return {
        ...state,
        documents: [...state.documents, {
          documentId: action.documentId,
          docType: action.docType,
          at: action.at,
        }],
      }
    }
  }
}

/**
 * The one place a profile patch lands. `writeFields` records each patched
 * key's bridged field too (agent path — the applicant said it in chat, which
 * is as explicit as typing it); the panel path already wrote its own field.
 * A licence declaration answers each group's type either way.
 */
function applyProfilePatch(
  state: ApplicationState,
  patch: Partial<ApplicantProfile>,
  opts: { writeFields: boolean },
): ApplicationState {
  const profile: ApplicantProfile = { ...state.profile, ...patch }
  const fields: ApplicationState['fields'] = { ...state.fields }

  if (opts.writeFields) {
    for (const entry of PROFILE_BRIDGE) {
      if (!(entry.key in patch)) continue
      const value = entry.toFieldValue(profile[entry.key])
      if (value === null) {
        // Nothing to record is fine on a field never recorded; but a field
        // that already held a value must not stand confirmed once the
        // profile no longer backs it.
        const existing = fields[entry.fieldId]
        if (existing && existing.value !== null) {
          fields[entry.fieldId] = { value: null, status: 'empty' }
        }
        continue
      }
      // The panel path is guard-validated before the reducer; this is the
      // agent path's net — a value the catalog rejects must not become a
      // confirmed answer.
      if (!fieldDef(entry.fieldId).validation.safeParse(value).success) continue
      fields[entry.fieldId] = {
        value, status: 'confirmed', provenance: { source: 'user' },
      }
    }
  }

  // licenses_held is authoritative: a later licenses patch rewrites every
  // license_type#n here, discarding any manual per-group edit by design.
  for (const [index, type] of (patch.licenses ?? []).entries()) {
    fields[reqKey('license_type', index)] = {
      value: type,
      // Confirmed, not derived: the declaration itself was explicit input.
      status: 'confirmed',
      provenance: { source: 'carried', fromFieldId: reqKey('licenses_held') },
    }
  }

  const merged = { ...state, profile, fields }
  return { ...merged, fields: resyncFields(merged, profile) }
}

/**
 * Brings stored fields back into line with what the new profile requires: no
 * longer required becomes `superseded`, required again returns to `derived`
 * ("we still have this, look at it again") rather than counting as answered.
 *
 * Values are never deleted, only restatused. The supersession is not audited
 * separately — it is a deterministic function of the profile change, which is
 * audited together with rulesVersion.
 *
 * TODO(phase-4): resync on resume, when RULES_VERSION itself has moved.
 */
function resyncFields(
  state: ApplicationState,
  profile: ApplicantProfile,
): ApplicationState['fields'] {
  const required = new Set(requiredFields(profile))
  const next: ApplicationState['fields'] = { ...state.fields }

  for (const [key, field] of Object.entries(state.fields)) {
    if (!field) continue

    if (!required.has(key) && field.status !== 'superseded') {
      next[key] = { ...field, status: 'superseded' }
    } else if (required.has(key) && field.status === 'superseded' && field.value !== null) {
      next[key] = { ...field, status: 'derived' }
    }
  }

  return next
}

function withField(
  state: ApplicationState,
  id: RequirementKey,
  field: FieldState,
): ApplicationState {
  return { ...state, fields: { ...state.fields, [id]: field } }
}
